		instanceID=1267,
		order=2,
		name="Baron Braunpyke",
		lore="Distraught over the death of his brother, Baron Braunpyke has pledged his loyalty to Prioress Murrpray. The powerful knight now acts as her personal enforcer, protecting the secrets of the Priory from both outsiders and insufficiently loyal Arathi.",
		dungeonEncounterID=2835,
