		sections={
			{id=27758,title="Overview",body="Baron Braunpyke bends the light to his will, hurling his |cFF2959D3|Hspell:423015|h[Castigator's Shield]|h|r, and summoning |cFF2959D3|Hspell:423076|h[Hammers of Purity]|h|r from above.\n\nUpon reaching 100 Holy energy, Braunpyke empowers his abilities with |cFF2959D3|Hspell:422969|h[Vindictive Wrath]|h|r."},
			{id=27759,title="Tanks",body="$bullet; While empowered by |cFF2959D3|Hspell:422969|h[Vindictive Wrath]|h|r Baron Braunpyke's melee strike damage is increased.\n$bullet; |cFF2959D3|Hspell:423015|h[Castigator's Shield]|h|r leaves |cFF2959D3|Hspell:423019|h[Castigator's Detonation]|h|r at the location of each player hit."},
			{id=27760,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:423051|h[Burning Light]|h|r will heal Braunpyke and damage those around him if not interrupted.\n$bullet; |cFF2959D3|Hspell:423015|h[Castigator's Shield]|h|r leaves |cFF2959D3|Hspell:423019|h[Castigator's Detonation]|h|r at the location of each player hit."},
			{id=27761,title="Healers",body="$bullet; The damage during |cFF2959D3|Hspell:422969|h[Vindictive Wrath]|h|r is greatly increased.\n$bullet; |cFF2959D3|Hspell:423015|h[Castigator's Shield]|h|r leaves |cFF2959D3|Hspell:423019|h[Castigator's Detonation]|h|r at the location of each player hit."},
