		sections={
			{id=27814,title="Overview",body="Captain Dailcry is protected by his Trusted Guards, who gain |cFF2959D3|Hspell:424626|h[Strength in Numbers]|h|r while near each other. Captain Dailcry's loyal mount, Ember, ravages his enemies with |cFF2959D3|Hspell:447439|h[Savage Mauling]|h|r while he rallies his allies with a courageous |cFF2959D3|Hspell:424419|h[Battle Cry]|h|r."},
			{id=27817,title="Tank",body="$bullet; Captain Dailcry is protected by trusted guards who gain |cFF2959D3|Hspell:424628|h[Strength in Numbers]|h|r.\n$bullet; |cFF2959D3|Hspell:424419|h[Battle Cry]|h|r  increases damage done by Captain Dailcry and his allies.\n$bullet; |cFF2959D3|Hspell:424414|h[Pierce Armor]|h|r inflicts heavy bleed damage to Captain Dailcry's current target.",difficultyIDs={1,2}},
			{id=27815,title="Damage Dealers",body="$bullet; Captain Dailcry is protected by trusted guards who gain |cFF2959D3|Hspell:424628|h[Strength in Numbers]|h|r.\n$bullet; Ember attacks a player with |cFF2959D3|Hspell:447439|h[Savage Mauling]|h|r until Captain Dailcry's shield is broken.\n$bullet; |cFF2959D3|Hspell:1238782|h[Earthshattering Spear]|h|r inflicts heavy damage to players in the impact area.",difficultyIDs={1,2}},
			{id=27816,title="Healer",body="$bullet; |cFF2959D3|Hspell:447439|h[Savage Mauling]|h|r inflicts heavy damage to the player caught in Ember's clutches.\n$bullet; |cFF2959D3|Hspell:1238782|h[Earthshattering Spear]|h|r inflicts heavy damage to players in the impact area.\n$bullet; |cFF2959D3|Hspell:424414|h[Pierce Armor]|h|r inflicts heavy bleed damage to Captain Dailcry's current target.",difficultyIDs={1,2}},
			{id=27820,title="Tank",body="$bullet; Captain Dailcry is protected by trusted guards who gain |cFF2959D3|Hspell:424628|h[Strength in Numbers]|h|r.\n$bullet; |cFF2959D3|Hspell:424419|h[Battle Cry]|h|r  increases damage done by Captain Dailcry and his allies.\n$bullet; |cFF2959D3|Hspell:424414|h[Pierce Armor]|h|r inflicts heavy bleed damage to Captain Dailcry's current target.",difficultyIDs={8,23}},
