	[2579]={
		encounterID=2579,
		instanceID=1269,
		order=0,
		name="Skarmorak",
		lore="The High Speaker spent countless years attempting to restore the Awakening Machine. One failed attempt resulted in a new horror: a golem infused with skardyn corruption. Crystals augment its elemental configuration. Though it barely communicates its alien mindset, its hatred for all creation is undeniable.",
		dungeonEncounterID=2880,
		uiMapID=2341,
		pin={x=0.8021,y=0.3252},
		difficultyIDs={1,2,8,23,205},
		npcIDs={83343,155333},
		displayIDs={37518,118714},
		loot={
