		sections={
			{id=28132,title="Overview",body="Angered by the Order of Night's failure to capture the Dawnbreaker, Speaker Shadowcrown joins the fray wielding powerful shadow magic. \n\nAt 50% and 1% health remaining Shadowcrown unleashes |cFF2959D3|Hspell:451026|h[Darkness Comes]|h|r in an attempt to destroy any players left aboard the Dawnbreaker."},
			{id=28133,title="Healers",body="$bullet;|cFF2959D3|Hspell:426734|h[Burning Shadows]|h|r applies |cFF2959D3|Hspell:426736|h[Shadow Shroud]|h|r when removed.\n$bullet;|cFF2959D3|Hspell:451026|h[Darkness Comes]|h|r kills any players left aboard the Dawnbreaker.\n$bullet;|cFF2959D3|Hspell:449042|h[Radiant Light]|h|r allows skyriding and mounting in combat.",difficultyIDs={1,2}},
			{id=30214,title="Healers",body="$bullet;|cFF2959D3|Hspell:453212|h[Obsidian Beam]|h|r inflict high damage and rotates over its duration.\n$bullet;|cFF2959D3|Hspell:451026|h[Darkness Comes]|h|r kills any players left aboard the Dawnbreaker.\n$bullet;|cFF2959D3|Hspell:449042|h[Radiant Light]|h|r allows skyriding and mounting in combat.",difficultyIDs={8,23}},
			{id=30215,title="Tanks",body="$bullet;|cFF2959D3|Hspell:425264|h[Obsidian Blast]|h|r inflicts high damage.\n$bullet;|cFF2959D3|Hspell:451026|h[Darkness Comes]|h|r kills any players left aboard the Dawnbreaker.\n$bullet;|cFF2959D3|Hspell:449042|h[Radiant Light]|h|r allows skyriding and mounting in combat.",difficultyIDs={1,2}},
