			{id=30216,title="Damage Dealers",body="$bullet;The size of |cFF2959D3|Hspell:445996|h[Collapsing Darkness]|h|r increases with each explosion.\n$bullet;|cFF2959D3|Hspell:451026|h[Darkness Comes]|h|r kills any players left aboard the Dawnbreaker.\n$bullet;|cFF2959D3|Hspell:449042|h[Radiant Light]|h|r allows skyriding and mounting in combat.",difficultyIDs={1,2}},
