		order=2,
		name="Anub'ikkaj",
		lore="Anub'ikkaj is one of Queen Ansurek's most brilliant tacticians. A meticulous planner known for creative use of indigenous resources. His soldiers are fanatically loyal.",
		dungeonEncounterID=2838,
		uiMapID=2359,
