	[2582]={
		encounterID=2582,
		instanceID=1269,
		order=4,
		name="Void Speaker Eirich",
		lore="Eirich has been deposed, his authority seized! Overwhelmed, he fled to the innermost sanctum of the Stonevault. Yet in his machinations, he succumbed to transformation: Void energy from a malfunctioning artifact corrupts his living stone! Mystical revelations now shatter his sanity.",
		dungeonEncounterID=2883,
		uiMapID=2341,
		pin={x=0.538,y=0.7549},
		difficultyIDs={1,2,8,23,205},
		npcIDs={213119},
		displayIDs={119856},
		loot={
			{itemID=219303,diffs={},faction=-1},
			{itemID=221095,diffs={},faction=-1},
			{itemID=221090,diffs={},faction=-1},
			{itemID=221091,diffs={},faction=-1},
