		},
	},
	[2583]={
		encounterID=2583,
		instanceID=1271,
		order=1,
		name="Avanoxx",
		lore="Deserted when Ara-Kara fell to ruin, the creature known as Avanoxx started as nothing more than a humble spider. Years of isolation in an area ripe for feeding have left her free to grow, overseeing her children, her followers, and her territory with unmatched size and ferocity.",
		dungeonEncounterID=2926,
		uiMapID=2357,
		pin={x=0.6782,y=0.2838},
		difficultyIDs={1,2,8,23,205},
		npcIDs={218152},
		displayIDs={114552,119793},
		loot={
			{itemID=219314,diffs={},faction=-1},
			{itemID=221153,diffs={},faction=-1},
			{itemID=221152,diffs={},faction=-1},
			{itemID=221151,diffs={},faction=-1},
			{itemID=221150,diffs={},faction=-1},
		},
		sections={
			{id=28393,title="Overview",body="Avanoxx consumes with |cFF2959D3|Hspell:438471|h[Voracious Bites]|h|r and signals to Starved Crawlers with |cFF2959D3|Hspell:438476|h[Alerting Shrill]|h|r that grow in |cFF2959D3|Hspell:438490|h[Hunger]|h|r over time. \n\nAvanoxx unleashes |cFF2959D3|Hspell:438473|h[Gossamer Onslaught]|h|r and causes additional undercrawler eggs to fall from above. |cFF2959D3|Hspell:434830|h[Vile Webbing]|h|r serves as the perfect trap for her prey.\n$[!8,23 \nIn Mythic difficulty, Avanoxx becomes |cFF2959D3|Hspell:446788|h[Insatiable]|h|r.$]"},
			{id=28394,title="Tank",body="$bullet;|cFF2959D3|Hspell:438471|h[Voracious Bite]|h|r inflicts heavy damage to its target and increases damage taken for a period of time.\n$bullet; Standing in |cFF2959D3|Hspell:434830|h[Vile Webbing]|h|r causes |cFF2959D3|Hspell:436614|h[Web Wrap]|h|r.\n$bullet;|cFF2959D3|Hspell:438490|h[Hunger]|h|r causes Starved Crawlers to fixate on other players."},
			{id=28395,title="Damage Dealers",body="$bullet; Standing in |cFF2959D3|Hspell:434830|h[Vile Webbing]|h|r causes |cFF2959D3|Hspell:436614|h[Web Wrap]|h|r.\n$bullet; Starved Crawlers grow in |cFF2959D3|Hspell:438490|h[Hunger]|h|r over time."},
			{id=28396,title="Healer",body="$bullet; Standing in |cFF2959D3|Hspell:434830|h[Vile Webbing]|h|r causes |cFF2959D3|Hspell:436614|h[Web Wrap]|h|r.\n$bullet;|cFF2959D3|Hspell:438476|h[Alerting Shrill]|h|r and |cFF2959D3|Hspell:438473|h[Gossamer Onslaught]|h|r inflict substantial party-wide damage.\n$bullet;|cFF2959D3|Hspell:438471|h[Voracious Bite]|h|r inflicts heavy damage to its target and increases damage taken for a period of time."},
			{id=29111,title="Section 13",difficultyIDs={8,23}},
			{id=28810,title="Section 9"},
			{id=28811,title="Starved Crawler"},
			{id=28813,title="Section 12"},
			{id=28807,title="Section 6"},
			{id=28808,title="Section 7"},
			{id=28809,title="Section 8"},
		},
	},
	[2584]={
		encounterID=2584,
		instanceID=1271,
		order=2,
		name="Anub'zekt",
		lore="While Anub'zekt has not yet earned his own ascension, he has been granted the honor of overseeing the Ara-Kara harvesting operation. Fiercely tactical and immensely strong, Anub'zekt will not hesitate to step in should his forces prove insufficient in their defense of Ara-Kara.",
		dungeonEncounterID=2906,
		uiMapID=2357,
		pin={x=0.1697,y=0.3978},
		difficultyIDs={1,2,8,23,205},
		npcIDs={215405},
		displayIDs={115723,117870},
		loot={
			{itemID=219316,diffs={},faction=-1},
			{itemID=221157,diffs={},faction=-1},
			{itemID=221158,diffs={},faction=-1},
			{itemID=221154,diffs={1},faction=-1},
			{itemID=221156,diffs={},faction=-1},
			{itemID=221155,diffs={},faction=-1},
			{itemID=221154,diffs={},faction=-1},
		},
		sections={
			{id=28400,title="Overview",body="Anub'zekt fights fiercely alongside his brood, attacking with brutal |cFF2959D3|Hspell:433425|h[Impale]|h|r attacks while |cFF2959D3|Hspell:433747|h[Ceaseless Swarms]|h|r roam the battlefield. Upon reaching 100 energy, he calls upon his entire brood, dragging enemies into the |cFF2959D3|Hspell:433766|h[Eye of the Swarm]|h|r."},
			{id=28401,title="Tanks",body="$bullet; Anub'zekt fires |cFF2959D3|Hspell:433425|h[Impale]|h|r in front of himself, inflicting high damage and knocking back players hit.\n$bullet; |cFF2959D3|Hspell:433766|h[Eye of the Swarm]|h|r surrounds the arena and limits mobility."},
			{id=28402,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:433747|h[Ceaseless Swarms]|h|r burst forth from players infected by|cFF2959D3|Hspell:433740|h[Infestation]|h|r .\n$bullet; |cFF2959D3|Hspell:433677|h[Burrow Charge]|h|r inflicts high damage to players in a line in front of Anub'zekt."},
			{id=28403,title="Healers",body="$bullet; |cFF2959D3|Hspell:433747|h[Ceaseless Swarms]|h|r burst forth from players infected by|cFF2959D3|Hspell:433740|h[Infestation]|h|r .\n$bullet; |cFF2959D3|Hspell:433766|h[Eye of the Swarm]|h|r surrounds the arena and limits mobility."},
			{id=28864,title="Section 9"},
			{id=28975,title="Bloodstained Webmage",body="Bloodstained Webmages will attempt to trap players in webbing to make easy prey for Anub'zekt and his brood.",difficultyIDs={8,23}},
