			{id=28404,title="Stage One: <PH>"},
		},
	},
	[2585]={
		encounterID=2585,
		instanceID=1271,
		order=3,
		name="Ki'katal the Harvester",
		lore="As one of Ansurek's ascended, Ki'katal has been charged with overseeing the harvest of Black Blood from the very feet of the Queen's own citadel. Harsh and unrelenting, Ki'katal will stop at nothing to see the harvest continue, utilitzing every enhanced ability at her disposal.",
		dungeonEncounterID=2901,
		uiMapID=2358,
		pin={x=0.4685,y=0.559},
		difficultyIDs={1,2,8,23,205},
		npcIDs={215407},
		displayIDs={117473},
		loot={
			{itemID=219317,diffs={},faction=-1},
