			{itemID=223141,diffs={101},faction=-1},
			{itemID=223142,diffs={101},faction=-1},
			{itemID=223143,diffs={101},faction=-1},
		},
		sections={
			{id=28407,title="Overview",body="A stream of Bloodworkers ferry |cFF2959D3|Hspell:431985|h[Black Blood]|h|r for Ki'katal the Harvester. When struck, they drop their slime cargo and flee.\n\nUpon reaching 100 energy, Ki'katal the Harvester manifests a |cFF2959D3|Hspell:432117|h[Cosmic Singularity]|h|r, pulling all players in towards the detonation."},
			{id=28408,title="Tanks",body="$bullet;Stepping within Black Blood causes |cFF2959D3|Hspell:432031|h[Grasping Blood]|h|r to root players in place and prevent them from moving.\n$bullet;|cFF2959D3|Hspell:432117|h[Cosmic Singularity]|h|r pulls all players in and inflicts high damage."},
			{id=28409,title="Damage Dealers",body="$bullet;Stepping within Black Blood causes |cFF2959D3|Hspell:432031|h[Grasping Blood]|h|r to root players in place and prevent them from moving.\n$bullet;|cFF2959D3|Hspell:432117|h[Cosmic Singularity]|h|r pulls all players in and inflicts high damage."},
			{id=28410,title="Healers",body="$bullet;Stepping within Black Blood causes |cFF2959D3|Hspell:432031|h[Grasping Blood]|h|r to root players in place and prevent them from moving.\n$bullet;|cFF2959D3|Hspell:432117|h[Cosmic Singularity]|h|r pulls all players in and inflicts high damage."},
			{id=28411,title="Bloodworkers",body="Bloodworkers carry Black Blood. Any damage taken causes the drone to drop it and flee."},
			{id=28573,title="Black Blood",body="$[!8,23\n\nOn Mythic difficulty, Black Blood is absorbed after a single player steps in it.$]"},
			{id=28574,title="Cosmic Singularity"},
