	[2586]={
		encounterID=2586,
		instanceID=1272,
		order=1,
		name="Brew Master Aldryr",
		lore="Barkeep and brew master for the meadery, Aldryr has more than mead on tap. Anyone who messes with the Cinderbrew Meadery's new management messes with Aldryr, and he has many friends in low places.",
		dungeonEncounterID=2900,
		uiMapID=2335,
		pin={x=0.4451,y=0.5213},
		difficultyIDs={1,2,8,23,205},
		npcIDs={210271},
		displayIDs={116429,119017},
		loot={
			{itemID=219297,diffs={},faction=-1},
			{itemID=221051,diffs={},faction=-1},
			{itemID=221053,diffs={},faction=-1},
			{itemID=221052,diffs={},faction=-1},
			{itemID=221054,diffs={},faction=-1},
		},
		sections={
			{id=28414,title="Overview",body="Brew Master Aldryr harnesses the explosive power of Cinderbrew, assaulting players with |cFF2959D3|Hspell:432198|h[Blazing Belch]|h|r and |cFF2959D3|Hspell:432182|h[Throw Cinderbrew]|h|r.\n\nAt 66% and 33% health, Brew Master Aldryr begins |cFF2959D3|Hspell:442525|h[Happy Hour]|h|r and causes Thirsty Patrons to unleash a |cFF2959D3|Hspell:431896|h[Rowdy Yell]|h|r."},
			{id=28415,title="Tanks",body="$bullet;Thirsty Patrons inflict Physical damage to all players with |cFF2959D3|Hspell:431896|h[Rowdy Yell]|h|r until appeased.\n$bullet;|cFF2959D3|Hspell:432229|h[Keg Smash]|h|r inflicts high Physical damage and forms pools of |cFF2959D3|Hspell:432196|h[Hot Honey]|h|r."},
			{id=28416,title="Damage Dealers",body="$bullet;Thirsty Patrons inflict Physical damage to all players with |cFF2959D3|Hspell:431896|h[Rowdy Yell]|h|r until appeased.\n$bullet;|cFF2959D3|Hspell:432198|h[Blazing Belch]|h|r inflicts high Fire damage towards a player in a frontal cone."},
			{id=28417,title="Healers",body="$bullet;Thirsty Patrons inflict Physical damage to all players with |cFF2959D3|Hspell:431896|h[Rowdy Yell]|h|r until appeased.\n$bullet;|cFF2959D3|Hspell:432182|h[Throw Cinderbrew]|h|r inflicts significant Fire damage to targeted players."},
			{id=28964,title="Section 12",body="$[!8,23,\n\nOn Mythic difficulty, Crawling Brawls occur when Happy Hour ends.$]"},
