	[2587]={
		encounterID=2587,
		instanceID=1272,
		order=1,
		name="I'pa",
		lore="The product of an industrial accident, mead elemental I'pa is as angry about its existence as it is about its meadery being disturbed. It is the full-bodied embodiment of the fiery punch of cinderbrew mead, and will lay anyone who tangles with it out flat.",
		dungeonEncounterID=2929,
		uiMapID=2335,
		pin={x=0.4132,y=0.2366},
		difficultyIDs={1,2,8,23,205},
		npcIDs={210267},
		displayIDs={117177,117828},
		loot={
			{itemID=221056,diffs={},faction=-1},
			{itemID=221057,diffs={},faction=-1},
			{itemID=221058,diffs={},faction=-1},
