			{itemID=221059,diffs={},faction=-1},
			{itemID=221061,diffs={},faction=-1},
		},
		sections={
			{id=28421,title="Overview",body="$[1,2I'pa embodies Cinderbrew itself, assailing players with |cFF2959D3|Hspell:439365|h[Spouting Stout]|h|r and |cFF2959D3|Hspell:439202|h[Burning Fermentation]|h|r. Brew Drops cause |cFF2959D3|Hspell:440104|h[Fill 'Er Up]|h|r if they reach I'pa. Defeating them creates pools of |cFF2959D3|Hspell:440087|h[Oozing Honey]|h|r that shrink.$]$[8,23I'pa embodies Cinderbrew itself, assailing players with |cFF2959D3|Hspell:439365|h[Spouting Stout]|h|r and |cFF2959D3|Hspell:439202|h[Burning Fermentation]|h|r. Brew Drops cause |cFF2959D3|Hspell:440104|h[Fill 'Er Up]|h|r if they reach I'pa. Defeating them creates pools of |cFF2959D3|Hspell:440087|h[Oozing Honey]|h|r that shrink until the drops reform.$]"},
			{id=28422,title="Tanks",body="$bullet;|cFF2959D3|Hspell:439031|h[Bottoms Uppercut]|h|r inflicts high Physical damage and knocks the targeted player back.\n$bullet;|cFF2959D3|Hspell:439365|h[Spouting Stout]|h|r creates Brew Drops and inflicts moderate Fire damage to all players."},
			{id=28423,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:439365|h[Spouting Stout]|h|r creates Brew Drops and inflicts moderate Fire damage to all players.\n$bullet;Brew Drops cause |cFF2959D3|Hspell:440104|h[Fill 'Er Up]|h|r  if they reach I'pa."},
			{id=28424,title="Healers",body="$bullet;|cFF2959D3|Hspell:439202|h[Burning Fermentation]|h|r inflicts high Fire damage to afflicted players unless dispelled.\n$bullet;|cFF2959D3|Hspell:439365|h[Spouting Stout]|h|r creates Brew Drops and inflicts moderate Fire damage to all players."},
			{id=28426,title="Section 7"},
			{id=29566,title="Brew Drop",body="Brew Drops move towards I'pa upon forming.",difficultyIDs={1,2}},
			{id=29567,title="Section 10"},
