		},
		sections={
			{id=28428,title="Overview",body="Benk Buzzbee distributes barrels of delicious honey during |cFF2959D3|Hspell:438025|h[Snack Time]|h|r, attracting Ravenous Cinderbees.\n\nDefeated Cinderbees become docile enough to be mounted by players and will charge forward with a |cFF2959D3|Hspell:438763|h[Bee-Haw!]|h|r command."},
			{id=28429,title="Tanks",body="$bullet;|cFF2959D3|Hspell:440134|h[Honey Marinade]|h|r  drips off targeted players on expiration, creating pools of flaming honey that inflict Fire Damage.\n$bullet;|cFF2959D3|Hspell:438025|h[Snack Time]|h|r barrels in the arena will periodically attract Ravenous Cinderbees."},
			{id=28430,title="Damage Dealers",body="$bullet;At 1 HP, Ravenous Cinderbees become tame enough to be ridden by players.\n$bullet;|cFF2959D3|Hspell:438025|h[Snack Time]|h|r barrels are destroyed by the impact of a Ravenous Cinderbee charging forward with a |cFF2959D3|Hspell:438763|h[Bee-Haw!]|h|r"},
			{id=28431,title="Healers",body="$bullet;|cFF2959D3|Hspell:439524|h[Fluttering Wing]|h|r inflicts moderate Nature damage to all players.\n$bullet;Ravenous Cinderbees dart between random players with |cFF2959D3|Hspell:438971|h[Shredding Sting]|h|r, afflicting them with a stacking Bleed debuff."},
			{id=28852,title="Section 8"},
			{id=28853,title="Ravenous Cinderbee"},
			{id=28855,title="Section 9"},
			{id=30180,title="Section 13"},
			{id=28856,title="Section 10"},
			{id=29039,title="Section 11",body="$[!8,23,\n\nOn Mythic difficulty, Ravenous Cinderbees standing within the effect will become Honey Gorged.$]",difficultyIDs={8,23}},
			{id=29040,title="Section 11",difficultyIDs={8,23}},
			{id=28854,title="Section 7"},
			{id=28857,title="Section 11",difficultyIDs={1,2}},
		},
	},
	[2589]={
		encounterID=2589,
		instanceID=1272,
		order=1,
		name="Goldie Baronbottom",
		lore="Savvy businesswoman Goldie Baronbottom knows a good opportunity when she sees it--like the Cinderbrew Meadery. After barging in and swindling Wenbrandt out of business, Goldie mostly lets her cronies do the work. Even so, she's not afraid to roll up her sleeves and wallop do-gooders herself.",
		dungeonEncounterID=2930,
		uiMapID=2335,
		pin={x=0.5494,y=0.5288},
		difficultyIDs={1,2,8,23,205},
		npcIDs={214661,222318},
		displayIDs={118000},
		loot={
			{itemID=219299,diffs={},faction=-1},
			{itemID=221072,diffs={},faction=-1},
			{itemID=221071,diffs={},faction=-1},
			{itemID=221070,diffs={},faction=-1},
