		sections={
			{id=28564,title="Overview",body="Rasha'nan sinks her claws into The Dawnbreaker as Nightfall Bombers hurl |cFF2959D3|Hspell:434655|h[Arathi Bomb]|h|rs aboard the airship.\n\nAfter suffering enough damage from the bombs' explosions, Rasha'nan takes flight across Hallowfall and begins to cast |cFF2959D3|Hspell:449734|h[Acidic Eruption]|h|r until interrupted."},
			{id=28565,title="Healers",body="$bullet;|cFF2959D3|Hspell:434089|h[Spinneret's Strands]|h|r inflict party-wide damage when snapped.\n$bullet;Waves of |cFF2959D3|Hspell:434407|h[Rolling Acid]|h|r move in the targeted direction and corrode any |cFF2959D3|Hspell:434096|h[Sticky Webs]|h|r into |cFF2959D3|Hspell:438957|h[Acid Pool]|h|rs.\n$bullet;|cFF2959D3|Hspell:449042|h[Radiant Light]|h|r allows skyriding and mounting in combat."},
			{id=28566,title="Tanks",body="$bullet;|cFF2959D3|Hspell:434655|h[Arathi Bomb]|h|rs inflict substantial damage to Rasha'nan.\n$bullet;Waves of |cFF2959D3|Hspell:434407|h[Rolling Acid]|h|r move in the targeted direction and corrode any |cFF2959D3|Hspell:434096|h[Sticky Webs]|h|r into |cFF2959D3|Hspell:438957|h[Acid Pool]|h|rs.\n$bullet;|cFF2959D3|Hspell:449042|h[Radiant Light]|h|r allows skyriding and mounting in combat."},
			{id=28567,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:434655|h[Arathi Bomb]|h|rs inflict substantial damage to Rasha'nan.\n$bullet;Waves of |cFF2959D3|Hspell:434407|h[Rolling Acid]|h|r move in the targeted direction and corrode any |cFF2959D3|Hspell:434096|h[Sticky Webs]|h|r into |cFF2959D3|Hspell:438957|h[Acid Pool]|h|rs.\n$bullet;|cFF2959D3|Hspell:449042|h[Radiant Light]|h|r allows skyriding and mounting in combat."},
