	[2594]={
		encounterID=2594,
		instanceID=1274,
		order=1,
		name="Orator Krix'vizk",
		lore="Orator Krix'vizk of the Fifth Strand desires nothing more than ascension, and spends his days extolling the virtues of Queen Ansurek in hopes of gaining her favor. Despite his obsession, he is not without his defenses. Should any cross the Orator, they will find the sound of his bark is far, far worse than his bite.",
		dungeonEncounterID=2907,
		uiMapID=2343,
		pin={x=0.5998,y=0.268},
		difficultyIDs={1,2,8,23,205},
		npcIDs={216619},
		displayIDs={116692},
		loot={
			{itemID=219318,diffs={},faction=-1},
			{itemID=221170,diffs={},faction=-1},
