		},
	},
	[2595]={
		encounterID=2595,
		instanceID=1274,
		order=2,
		name="Fangs of the Queen",
		lore="Twins Nx and Vx were born together, raised together, and trained in the ways of subterfuge and assassination together. A deadly pair, they earned their ascension together as well. Together they now serve as Fangs of the Queen, taking out any would-be threats to Ansurek's reign with relish.",
		dungeonEncounterID=2908,
		uiMapID=2343,
		pin={x=0.7046,y=0.488},
		difficultyIDs={1,2,8,23,205},
		npcIDs={216648,216649},
		displayIDs={115017,115776},
		loot={
			{itemID=219319,diffs={},faction=-1},
