		order=4,
		name="Izo, the Grand Splicer",
		lore="Evolution has long been a central part of nerubian life, and none possess greater passion or mastery of this process than Izo. Granted the methods of ascension by Ansurek, Izo pursues this path of perfection with determination, and little concern for who she serves, to what end, or at what cost.",
		dungeonEncounterID=2909,
		uiMapID=2344,
		pin={x=0.501,y=0.7844},
		difficultyIDs={1,2,8,23,205},
		npcIDs={216658},
