		sections={
			{id=28596,title="Overview",body="Izo creates a set of |cFF2959D3|Hspell:439401|h[Shifting Anomalies]|h|r, then shows off her mastery of transformation with |cFF2959D3|Hspell:438860|h[Umbral Weave]|h|r and |cFF2959D3|Hspell:437700|h[Tremor Slam]|h|r .\n\nUpon reaching 100 energy, Izo attempts to eliminate her target and anyone near them with |cFF2959D3|Hspell:439646|h[Process of Elimination]|h|r."},
			{id=28597,title="Tanks",body="$bullet;|cFF2959D3|Hspell:439401|h[Shifting Anomalies]|h|r inflict damage and knock back players on contact.\n$bullet;|cFF2959D3|Hspell:439646|h[Process of Elimination]|h|r inflicts heavy damage to Izo's target and to nearby players."},
			{id=28598,title="Damage Dealers",body="$bullet;Webs created by |cFF2959D3|Hspell:438860|h[Umbral Weave]|h|r can be attacked and destroyed.\n$bullet;|cFF2959D3|Hspell:439401|h[Shifting Anomalies]|h|r inflict damage and knock back players on contact.\n$bullet;|cFF2959D3|Hspell:439646|h[Process of Elimination]|h|r inflicts heavy damage to Izo's target and to nearby players."},
			{id=28599,title="Healers",body="$bullet;|cFF2959D3|Hspell:439401|h[Shifting Anomalies]|h|r inflict damage and knock back players on contact.\n$bullet;|cFF2959D3|Hspell:439646|h[Process of Elimination]|h|r inflicts heavy damage to Izo's target and to nearby players.\n$bullet;|cFF2959D3|Hspell:439341|h[Splice]|h|r inflicts significant damage to all party members."},
