	[2599]={
		encounterID=2599,
		instanceID=1273,
		order=3,
		name="Sikran, Captain of the Sureki",
		lore="Sikran established himself as an arrogant duelist within Queen Ansurek's court. Never knowing the cut of an enemy's blade, Sikran dispatched his rivals one-by-one and was proclaimed Captain of the Sureki by the queen herself. This indomitable fighter now ensures that any who threaten his queen fall before the throne's might.",
		dungeonEncounterID=2898,
		uiMapID=2293,
		pin={x=0.5905,y=0.301},
		difficultyIDs={14,15,16,17,220},
