	[2600]={
		encounterID=2600,
		instanceID=1274,
		order=3,
		name="The Coaglamation",
		lore="The Grand Splicer's evolutionary experiments often result in by-products of waste and sludge. This abhorrent glop may appear useless to some, but to Izo's clever ingenuity, it offers excellent material components for more experiementation--and a vicious monstrosity waiting to come to life.",
		dungeonEncounterID=2905,
		uiMapID=2344,
		pin={x=0.5,y=0.4701},
		difficultyIDs={1,2,8,23,205},
		npcIDs={216320},
		displayIDs={117254},
		loot={
			{itemID=219320,diffs={},faction=-1},
			{itemID=221182,diffs={},faction=-1},
			{itemID=221180,diffs={},faction=-1},
