		sections={
			{id=28745,title="Overview",body="Ky'veza marks targets for their |cFF2959D3|Hspell:436867|h[Assassination]|h|r while haunting |cFF2959D3|Hspell:437371|h[Nether Phantoms]|h|r emerge from her shadow to mirror the massacre.\n\nUpon reaching 100 energy, Ky'veza invokes a |cFF2959D3|Hspell:435405|h[Starless Night]|h|r as phantoms slaughter her enemies in the darkness."},
			{id=28746,title="Tanks",body="$bullet;|cFF2959D3|Hspell:440576|h[Chasmal Gash]|h|r increases damage taken from each strike of |cFF2959D3|Hspell:440377|h[Void Shredders]|h|r.\n$bullet;Players pulled into a |cFF2959D3|Hspell:437620|h[Nether Rift]|h|r become |cFF2959D3|Hspell:437786|h[Atomized]|h|r.\n$bullet;|cFF2959D3|Hspell:436749|h[Reaper]|h|r attemps to execute players that are low health."},
			{id=28747,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:436867|h[Assassination]|h|r creates |cFF2959D3|Hspell:437371|h[Nether Phantoms]|h|r that mirror some of Ky'veza's abilities.\n$bullet;Players pulled into a |cFF2959D3|Hspell:437620|h[Nether Rift]|h|r become |cFF2959D3|Hspell:437786|h[Atomized]|h|r.\n$bullet;|cFF2959D3|Hspell:436749|h[Reaper]|h|r attemps to execute players that are low health."},
			{id=28748,title="Healers",body="$bullet;|cFF2959D3|Hspell:436749|h[Reaper]|h|r attemps to execute players that are low health.\n$bullet;|cFF2959D3|Hspell:435405|h[Starless Night]|h|r and |cFF2959D3|Hspell:435486|h[Regicide]|h|r inflict heavy damage across the raid.\n$bullet;Players pulled into a |cFF2959D3|Hspell:437620|h[Nether Rift]|h|r become |cFF2959D3|Hspell:437786|h[Atomized]|h|r."},
