	[2602]={
		encounterID=2602,
		instanceID=1273,
		order=8,
		name="Queen Ansurek",
		lore="After a revelation of traitors in her court, Queen Ansurek decides she must eradicate the palace's invaders herself. However, paranoia over whom she can trust gnaws at her psyche. With her allies dwindling, Queen Ansurek may delve into dark powers to attain victory, even if that means her most loyal soldiers become her next meal...",
		dungeonEncounterID=2922,
		uiMapID=2295,
		pin={x=0.478,y=0.546},
		difficultyIDs={14,15,16,17,220},
		npcIDs={220586,225361},
		displayIDs={118481,118605,119348,119373,119403,119968,122687,122689},
		loot={
			{itemID=212454,diffs={},faction=-1},
			{itemID=225579,diffs={},faction=-1},
			{itemID=212394,diffs={},faction=-1},
