	[2607]={
		encounterID=2607,
		instanceID=1273,
		order=1,
		name="Ulgrax the Devourer",
		lore="Queen Ansurek's evolutionary experimentation created a number of monstrous guardians for her throne, none more voracious than Ulgrax the Devourer. Driven mad by endless hunger, Ulgrax is now the ravenous protector of Queen Ansurek's court.",
		dungeonEncounterID=2902,
		uiMapID=2292,
		pin={x=0.5324,y=0.3879},
		difficultyIDs={14,15,16,17,220},
		npcIDs={215657},
