			{itemID=212431,diffs={},faction=-1},
		},
		sections={
			{id=28833,title="Overview",body="Ulgrax attempts to devour players by engaging in a |cFF2959D3|Hspell:434799|h[Carnivorous Contest]|h|r and places globs of |cFF2959D3|Hspell:439502|h[Stalker's Webbing]|h|r throughout the arena.\n\nAt zero energy, Ulgrax goes mad with hunger, attacking players with |cFF2959D3|Hspell:436217|h[Juggernaut Charge]|h|r. Ulgrax then demands to be fed, unleashing |cFF2959D3|Hspell:458074|h[Hungering Bellows]|h|r until his energy is brought to full."},
			{id=30018,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:439502|h[Stalker's Webbing]|h|r  will root players on contact.\n$bullet;Ravenous Spawn continually |cFF2959D3|Hspell:439037|h[Disembowel]|h|r a player.",difficultyIDs={14,15,17}},
			{id=28834,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:439502|h[Stalker's Webbing]|h|r  will trap players and nearby allies in |cFF2959D3|Hspell:455831|h[Hardened Netting]|h|r on contact.\n$bullet;Ravenous Spawn continually |cFF2959D3|Hspell:439037|h[Disembowel]|h|r a player.",difficultyIDs={16}},
			{id=28835,title="Healers",body="$bullet;|cFF2959D3|Hspell:435138|h[Digestive Acid]|h|r inflicts significant damage to nearby allies when removed. \n$bullet;Each application of |cFF2959D3|Hspell:438041|h[Insatiable Rage]|h|r increases Ulgrax's damage."},
			{id=28836,title="Tanks",body="$bullet;Ravenous Spawn continually place applications of |cFF2959D3|Hspell:439037|h[Disembowel]|h|r on a player.\n$bullet;Excessively |cFF2959D3|Hspell:434705|h[Tenderized]|h|r players will become unable to be healed."},
			{id=30011,title="Gleeful Brutality"},
			{id=30135,title="Section 33",body="$[!16\n\nIn Mythic difficulty, bound players will emerge from the Contest |cFF2959D3|Hspell:455847|h[Battered and Bruised]|h|r. Ulgrax will enter a |cFF2959D3|Hspell:440849|h[Contemptful Rage]|h|r if fewer than $457668s3 players participate in the Contest.$]"},
