			{id=28912,title="Section 11"},
			{id=28909,title="Section 10",body="$[!15,16\n\nOn this difficulty, Spinneret's Strands tether affects all players in the damage radius.$]"},
			{id=28910,title="Section 12"},
			{id=30177,title="Section 22",body="$[!16\n\nOn this difficulty, the first player to unleash a Spinneret's Websnap triggers Tacky Threads.$]",difficultyIDs={16}},
			{id=28911,title="Section 11"},
			{id=28908,title="Section 7",body="$[!15,16\n\nOn this difficulty, Infested Spawn's initial damage affects players in a radius around the marked target.$]"},
			{id=29060,title="Section 19",body="$[!16\n\nOn this difficulty, Infested Bite additionally reduces movement speed.$]"},
