		name="The Bloodbound Horror",
		lore="In the dark pits below Nerub-ar Palace, the blood of the Old Gods congeals in foul, black pools. The Bloodbound Horror rises from this vile ooze - drawing everything in its path into The Unseeming.",
		dungeonEncounterID=2917,
		uiMapID=2291,
		pin={x=0.4355,y=0.6927},
		difficultyIDs={14,15,16,17,220},
