		sections={
			{id=28978,title="Section 1",body="Broodtwister Ovi'nax injects players with |cFF2959D3|Hspell:442526|h[Experimental Dosage]|h|r which causes nearby eggs to hatch upon expiration, unleashing the horrors within. \n\nUpon reaching 100 energy, Broodtwister Ovi'nax will |cFF2959D3|Hspell:442430|h[Ingest Black Blood]|h|r, growing in power and causing the room to slowly fill with |cFF2959D3|Hspell:442802|h[Sanguine Overflow]|h|r"},
			{id=28979,title="Tanks",body="$bullet;  |cFF2959D3|Hspell:441362|h[Volatile Concoction]|h|r inflicts damage to all players based on how much health the target is missing when it is removed.\n$bullet;  |cFF2959D3|Hspell:442802|h[Sanguine Overflow]|h|r mutates any creatures it comes into contact with.\n$bullet;  Colossal Spiders inflict increasing damage with |cFF2959D3|Hspell:438807|h[Vicious Bite]|h|r ."},
			{id=28980,title="Damage Dealers",body="$bullet;  |cFF2959D3|Hspell:442526|h[Experimental Dosage]|h|r causes nearby eggs to hatch, unleashing the horrific experiments incubating within.\n$bullet;  |cFF2959D3|Hspell:446349|h[Sticky Web]|h|r immobilizes nearby players when removed.\n$bullet; Blood Parasites |cFF2959D3|Hspell:442257|h[Infest]|h|r their target upon reaching them."},
			{id=28981,title="Healers",body="$bullet;  |cFF2959D3|Hspell:442526|h[Experimental Dosage]|h|r causes nearby eggs to hatch, unleashing the horrific experiments incubating within.\n$bullet; Broodtwister Ovi'nax inflicts increasing Shadow damage and healing absorbs as he receives more |cFF2959D3|Hspell:450362|h[Unstable Infusions]|h|r.\n$bullet; |cFF2959D3|Hspell:441362|h[Volatile Concoction]|h|r inflicts damage to all players based on how much health the target is missing when it is removed."},
			{id=28982,title="Section 5",difficultyIDs={14,15,17}},
			{id=30246,title="Experimental Dosage",body="$[!16\n\nOn Mythic difficulty, 2 simultaneous Experimental Dosage are required to cause a nearby egg to hatch.$]",difficultyIDs={16}},
