	[2625]={
		encounterID=2625,
		instanceID=1278,
		order=4,
		name="Orta, the Broken Mountain",
		lore="Long has this deepwalker strode through the chasms and legends of Azj-Kahet. His voice an earthquake, his will diamond, his strength adamant. Yet now he comes before Azj-Kahet, contaminated by the dark pustules of the black blood, in need of a good death. Who will rise to face him?",
		dungeonEncounterID=2984,
		pin={x=0.5,y=0.5},
		difficultyIDs={14},
		npcIDs={221067},
		displayIDs={119835},
		loot={
			{itemID=225734,diffs={},faction=-1},
			{itemID=225735,diffs={},faction=-1},
			{itemID=225751,diffs={},faction=-1},
			{itemID=225733,diffs={},faction=-1},
			{itemID=225731,diffs={},faction=-1},
			{itemID=225745,diffs={},faction=-1},
			{itemID=225732,diffs={},faction=-1},
			{itemID=225746,diffs={},faction=-1},
			{itemID=225730,diffs={},faction=-1},
		},
		sections={
			{id=29746,title="Overview",body="Orta rattles against the shackles of his infection, shattering the ground with |cFF2959D3|Hspell:450407|h[Colossal Slam]|h|r and invoking |cFF2959D3|Hspell:450677|h[Rupturing Runes]|h|r.\n\nAt 100 energy, Orta will cast |cFF2959D3|Hspell:450454|h[Tectonic Roar]|h|r, knocking all players away with his bellow."},
			{id=29747,title="Tanks",body="$bullet;|cFF2959D3|Hspell:450677|h[Rupturing Runes]|h|r stun players when triggered.\n\n$bullet;|cFF2959D3|Hspell:450454|h[Tectonic Roar]|h|r knocks players back a significant distance.\n\n$bullet;Players caught in |cFF2959D3|Hspell:450929|h[Mountain's Grasp]|h|r will be thrown by |cFF2959D3|Hspell:451702|h[Discard Weaklings]|h|r."},
			{id=29749,title="Healers",body="$bullet;|cFF2959D3|Hspell:450677|h[Rupturing Runes]|h|r stun players when triggered.\n\n$bullet;|cFF2959D3|Hspell:450454|h[Tectonic Roar]|h|r knocks players back a significant distance.\n\n$bullet;Players caught in |cFF2959D3|Hspell:450929|h[Mountain's Grasp]|h|r will be thrown by |cFF2959D3|Hspell:451702|h[Discard Weaklings]|h|r."},
			{id=29748,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:450677|h[Rupturing Runes]|h|r stun players when triggered.\n\n$bullet;|cFF2959D3|Hspell:450454|h[Tectonic Roar]|h|r knocks players back a significant distance.\n\n$bullet;Players caught in |cFF2959D3|Hspell:450929|h[Mountain's Grasp]|h|r will be thrown by |cFF2959D3|Hspell:451702|h[Discard Weaklings]|h|r."},
		},
	},
	[2635]={
		encounterID=2635,
		instanceID=1278,
		order=2,
		name="Aggregation of Horrors",
		lore="An abomination birthed from void-tainted remnants of Skardyn, the Aggregation of Horrors stands as a unified monstrosity. This dread entity is poised to unleash its terrifying plague upon The Ringing Deeps.",
		dungeonEncounterID=2988,
		pin={x=0.5,y=0.5},
		difficultyIDs={14},
		npcIDs={220999,222492,223813},
		displayIDs={117974,119659},
		loot={
			{itemID=225734,diffs={},faction=-1},
			{itemID=225735,diffs={},faction=-1},
			{itemID=225733,diffs={},faction=-1},
			{itemID=225731,diffs={},faction=-1},
			{itemID=225745,diffs={},faction=-1},
			{itemID=225732,diffs={},faction=-1},
			{itemID=225746,diffs={},faction=-1},
			{itemID=225749,diffs={},faction=-1},
			{itemID=225730,diffs={},faction=-1},
		},
		sections={
			{id=29927,title="Overview",body="The Aggregation of Horrors expels shards of rock during|cFF2959D3|Hspell: 452210|h [Crystalline Barrage]|h|r. These shards arise Fractured Skardyn during|cFF2959D3|Hspell: 453271|h[Dark Awakening]|h|r."},
			{id=29928,title="Tanks",body="$bullet;|cFF2959D3|Hspell: 453298|h[Crystal Strike]|h|r inflicts heavy Shadow damage on impact and over time.\n$bullet;|cFF2959D3|Hspell: 452981|h[Voidquake]|h|r inflicts Shadow damage to players caught within 150 yards."},
			{id=29929,title="Healer",body="$bullet;|cFF2959D3|Hspell: 452981|h[Voidquake]|h|r inflicts Shadow damage to players caught within 150 yards.\n$bullet;|cFF2959D3|Hspell: 452210|h[Crystalline Barrage]|h|r inflicts a large amount of damage to players hit by shards."},
			{id=29930,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell: 452981|h[Voidquake]|h|r inflicts Shadow damage to players caught within 150 yards.\n$bullet;The Aggregation of Horrors cast |cFF2959D3|Hspell: 456148|h[Annihilation Barrage]|h|r when no players are in melee combat.\n$bullet;|cFF2959D3|Hspell: 453271|h[Dark Awakening]|h|r creates Fractured Skardyn that attack nearby players."},
			{id=29959,title="Fractured Skardyn",body="Skardyn fractured from the Aggregation of Horrors' body."},
		},
	},
	[2636]={
		encounterID=2636,
		instanceID=1278,
		order=3,
		name="Shurrai, Atrocity of the Undersea",
		lore="The sea floor hides horrors beyond our imagining. Hallowfall's proximity to the Undersea brings it near the reach of creatures of the deep, and the kobyss are only eager to take advantage. Their summons raise Shurrai, Atrocity of the Undersea, to wreak havoc on their hunting grounds. Shurrai is an amalgamation of the worst terrors and putrefying flesh of the abyssal depths, and the Arathi will need all the help they can get to stop it.",
		dungeonEncounterID=2994,
		pin={x=0.5,y=0.5},
		difficultyIDs={14},
		npcIDs={221224},
		displayIDs={96784,115496},
		loot={
			{itemID=225734,diffs={},faction=-1},
			{itemID=225735,diffs={},faction=-1},
			{itemID=225733,diffs={},faction=-1},
			{itemID=225731,diffs={},faction=-1},
