			{itemID=225730,diffs={},faction=-1},
		},
		sections={
			{id=30005,title="Overview",body="Kordac defends Azeroth, targeting players with |cFF2959D3|Hspell:458209|h[Overcharged Lasers]|h|r which leave |cFF2959D3|Hspell:458799|h[Overcharged Earth]|h|r and |cFF2959D3|Hspell:459281|h[Empowering Coalescence]|h|r in their wake. Upon reaching 100 Energy, he rains down |cFF2959D3|Hspell:458423|h[Arcane Bombardment]|h|r."},
			{id=30006,title="Tanks",body="$bullet; Kordac's |cFF2959D3|Hspell:458320|h[Titanic Impact]|h|r inflicts high damage and launches players into the air.\n$bullet;|cFF2959D3|Hspell:458838|h[Supression Burst]|h|r pacifies and silences nearby players on detonation."},
			{id=30007,title="Healers",body="$bullet; |cFF2959D3|Hspell:458209|h[Overcharged Lasers]|h|r will pursue players and leave behind |cFF2959D3|Hspell:458799|h[Overcharged Earth]|h|r.\n$bullet;|cFF2959D3|Hspell:458838|h[Supression Burst]|h|r pacifies and silences any players near its target when it detonates."},
			{id=30008,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:459281|h[Empowering Coalescence]|h|r can be collected for a brief damage increase.\n$bullet; |cFF2959D3|Hspell:458209|h[Overcharged Lasers]|h|r will pursue players and leave behind |cFF2959D3|Hspell:458799|h[Overcharged Earth]|h|r."},
