	[2639]={
		encounterID=2639,
		instanceID=1296,
		order=1,
		name="Vexie and the Geargrinders",
		lore="Vexie Fullthrottle has been paving a path of terror through the hearts of anyone her gang encounters. Answering Gallywix's call for aid, she and her crew are here to repay an old favor, and add a few new grease stains to Undermine's streets.",
		dungeonEncounterID=3009,
		uiMapID=2406,
		pin={x=0.4729,y=0.4593},
		difficultyIDs={14,15,16,17,220},
		npcIDs={225821,225822},
		displayIDs={121716,121758,122443,122476,122477},
		loot={
