	[2640]={
		encounterID=2640,
		instanceID=1296,
		order=2,
		name="Cauldron of Carnage",
		lore="Throughout history there have been many epic wars, but none more explosive than the rivalry between the galvanic gorilla Torq the Tempest, and the molten mechasaur Flarendo the Furious. Tonight, all bets are off when these two champions clash in the cauldron for a showdown that threatens to tear Undermine in two! Witness the carnage or be the shame of goblin kind.",
		dungeonEncounterID=3010,
		uiMapID=2406,
		pin={x=0.506,y=0.1883},
		difficultyIDs={14,15,16,17,220},
		npcIDs={229177,229181,229287,229288,238586,238587},
