		sections={
			{id=30331,title="Overview",body="Flarendo and Torq put on a show for the audience, throwing |cFF2959D3|Hspell:473650|h[Scrapbombs]|h|r and afflicting arena combatants with |cFF2959D3|Hspell:473951|h[Static Charge]|h|r. \nUpon reaching 100 energy, Flarendo and Torq come together in a |cFF2959D3|Hspell:465833|h[Colossal Clash]|h|r!"},
			{id=30332,title="Tank",body="$bullet;|cFF2959D3|Hspell:472222|h[Blistering Spite]|h|r and |cFF2959D3|Hspell:472225|h[Galvanized Spite]|h|r  increase over time as players fight Flarendo and Torq.\n$bullet; |cFF2959D3|Hspell:1214190|h[Eruption Stomp]|h|r and |cFF2959D3|Hspell:1217933|h[Overload Burst]|h|r inflict heavy damage.\n$bullet; Flarendo and Torq take reduced damage while affected by |cFF2959D3|Hspell:471660|h[Raised Guard]|h|r."},
			{id=30334,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:472222|h[Blistering Spite]|h|r and |cFF2959D3|Hspell:472225|h[Galvanized Spite]|h|r  increase over time as players fight Flarendo and Torq.\n$bullet; |cFF2959D3|Hspell:473951|h[Static Charge]|h|r erupts into a |cFF2959D3|Hspell:473983|h[Static Discharge]|h|r once it builds to maximum charge.\n$bullet; |cFF2959D3|Hspell:473650|h[Scrapbomb]|h|r will inflict massive damage to the raid if no player is hit."},
			{id=30333,title="Healers",body="$bullet;|cFF2959D3|Hspell:472222|h[Blistering Spite]|h|r and |cFF2959D3|Hspell:472225|h[Galvanized Spite]|h|r  increase over time as players fight Flarendo and Torq.\n$bullet; |cFF2959D3|Hspell:473650|h[Scrapbomb]|h|r inflicts damage split evenly among players in its explosion radius.\n$bullet; |cFF2959D3|Hspell:465833|h[Colossal Clash]|h|r inflicts heavy damage to all players"},
