		sections={
			{id=31101,title="Overview",body="Rik Reverb places entrancing amplifiers around the yard during |cFF2959D3|Hspell:473748|h[Amplification]|h|r. Upon reaching full power, the amplifiers go |cFF2959D3|Hspell:466093|h[Haywire]|h|r.\n\nUpon reaching 100 energy, Rik unleashes |cFF2959D3|Hspell:467991|h[Blaring Drops]|h|r from his sonic resonator and causes each amplifier to |cFF2959D3|Hspell:466722|h[Blowout]|h|r."},
			{id=31102,title="Tanks",body="$bullet; Rik |cFF2959D3|Hspell:466128|h[Resonates]|h|r additional power to nearby amplifiers. \n$bullet; |cFF2959D3|Hspell:464488|h[Sonic Blast]|h|r inflicts Sonic damage in a frontal cone and applies |cFF2959D3|Hspell:464518|h[Tinnitus]|h|r. Sonic damage cannot be blocked or reduced by Armor.\n$bullet; Amplifier |cFF2959D3|Hspell:466722|h[Blowouts]|h|r knock players into the air as Rik generates deadly |cFF2959D3|Hspell:467991|h[Blaring Drops]|h|r."},
			{id=31103,title="Damage Dealers",body="$bullet; Activating amplifiers drains their energy but applies |cFF2959D3|Hspell:1217122|h[Lingering Voltage]|h|r.\n$bullet; Rik gains a nullifying |cFF2959D3|Hspell:1213817|h[Sound Cloud]|h|r in Stage Two.\n$bullet; Amplifier |cFF2959D3|Hspell:466722|h[Blowouts]|h|r  knock players into the air as Rik generates deadly |cFF2959D3|Hspell:467991|h[Blaring Drops]|h|r."},
			{id=31104,title="Healers",body="$bullet; Activating amplifiers drains their energy but applies |cFF2959D3|Hspell:1217122|h[Lingering Voltage]|h|r.\n$bullet; |cFF2959D3|Hspell:467044|h[Faulty Zap]|h|r inflicts damage to nearby players. \n$bullet; Amplifier |cFF2959D3|Hspell:466722|h[Blowouts]|h|r  knock players into the air as Rik generates deadly |cFF2959D3|Hspell:467991|h[Blaring Drops]|h|r."},
			{id=31656,title="Stage One: Party Starter"},
			{id=30386,title="Timed Release Audio Propagator"},
			{id=31087,title="Amplifier",body="The amplifier gains power over time."},
			{id=31493,title="Section 30",difficultyIDs={16}},
			{id=32007,title="Section 29",difficultyIDs={14,17}},
			{id=31379,title="Section 29",body="$[!15,16\n\nIn Heroic and Mythic difficulties, the electricity lingers, increasing the damage taken from Lingering Voltage by $1217122s2% for $1217122d. This effect stacks.$]",difficultyIDs={15,16}},
			{id=31721,title="Section 17",difficultyIDs={14,15,17}},
			{id=31722,title="Section 17",body="$[!16\n\nIn Mythic difficulty, players hit by Resonant Echoes while already under its effect become entranced.$]",difficultyIDs={16}},
