		sections={
			{id=30505,title="Overview",body="The two heads of Mug'Zee, Mug and Zee, begin the encounter in a friendly contest to see who is in control. Whichever head has $[16 all$]$[14,15,17the most$] players on their side of the arena becomes the |cFF2959D3|Hspell:466376|h[Head Honcho]|h|r, activating a unique set of abilities to unleash upon players.\n\nUpon reaching 40% remaining health, Mug and Zee combine their efforts and attack in unison granting them the use of all of their abilities at once."},
			{id=30506,title="Tanks",body="$bullet;|cFF2959D3|Hspell:466518|h[Molten Gold Knuckles]|h|r inflict heavy damage in front of Mug and apply |cFF2959D3|Hspell:467202|h[Golden Drip]|h|r to players hit.\n$bullet;Damage from |cFF2959D3|Hspell:469490|h[Double Whammy Shot]|h|r is mitigated by the closest player hit."},
			{id=31736,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:472631|h[Earthshaker Gaols]|h|r splits damage among all players within the effect, trapping them within earthen walls.\n$bullet;Touching |cFF2959D3|Hspell:466539|h[Unstable Crawler Mines]|h|r causes them to explode, unleashing an |cFF2959D3|Hspell:1220551|h[Unstable Cluster Bomb]|h|r and causing all players to suffer from |cFF2959D3|Hspell:469043|h[Searing Shrapnel]|h|r.",difficultyIDs={14,17}},
			{id=30507,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:472631|h[Earthshaker Gaols]|h|r splits damage among all players within the effect, trapping them within earthen walls.\n$bullet;|cFF2959D3|Hspell:466480|h[Frostshatter Spears]|h|r inflict lethal damage to the first player or |cFF2959D3|Hspell:472631|h[Earthshaker Gaol]|h|r wall they hit.\n$bullet;Touching |cFF2959D3|Hspell:466539|h[Unstable Crawler Mines]|h|r causes them to explode, unleashing an |cFF2959D3|Hspell:1220551|h[Unstable Cluster Bomb]|h|r and causing all players to suffer from |cFF2959D3|Hspell:469043|h[Searing Shrapnel]|h|r.",difficultyIDs={15,16}},
			{id=31737,title="Healers",body="$bullet;|cFF2959D3|Hspell:468663|h[Elemental Calamity]|h|r and |cFF2959D3|Hspell:469715|h[Uncontrolled Burn]|h|r inflict persistent damage over time each time Mug'zee swaps which head is the |cFF2959D3|Hspell:466376|h[Head Honcho]|h|r.\n$bullet;Mug'Zee gains |cFF2959D3|Hspell:466385|h[Moxie]|h|r the longer each head is in command.",difficultyIDs={14,17}},
			{id=30508,title="Healers",body="$bullet;|cFF2959D3|Hspell:468663|h[Elemental Calamity]|h|r and |cFF2959D3|Hspell:469715|h[Uncontrolled Burn]|h|r inflict persistent damage over time each time Mug'zee swaps which head is the |cFF2959D3|Hspell:466376|h[Head Honcho]|h|r.\n$bullet;Mug'Zee gains |cFF2959D3|Hspell:466385|h[Moxie]|h|r the longer each head is in command.\n$bullet;|cFF2959D3|Hspell:466480|h[Frostshatter Spears]|h|r inflict lethal damage to the first player or |cFF2959D3|Hspell:472631|h[Earthshaker Gaol]|h|r wall they hit.",difficultyIDs={15,16}},
