	[2648]={
		encounterID=2648,
		instanceID=1298,
		order=1,
		name="Big M.O.M.M.A.",
		lore="A prototype mech code-named Big M.O.M.M.A., piloted by Silva Stratospark, has been deployed to the Waterworks as operational security in service of Gallywix's schemes. The mech boasts a dizzying array of communications equipment, bolstered by the Darkfuse's Black Blood experiments.",
		dungeonEncounterID=3020,
		uiMapID=2387,
		pin={x=0.305,y=0.595},
		difficultyIDs={1,2,8,23,205},
		npcIDs={226398},
		displayIDs={121758,122867},
		loot={
			{itemID=234491,diffs={},faction=-1},
			{itemID=234500,diffs={},faction=-1},
			{itemID=234503,diffs={},faction=-1},
			{itemID=234497,diffs={},faction=-1},
			{itemID=232542,diffs={},faction=-1},
			{itemID=246278,diffs={2,23},faction=-1},
			{itemID=251880,diffs={2,23},faction=-1},
		},
		sections={
			{id=30319,title="Overview",body="Big M.O.M.M.A. commands an army of drones that, when defeated, cause Big M.O.M.M.A. to |cFF2959D3|Hspell:460156|h[Jumpstart]|h|r, inflicting heavy damage to all players but causing Big M.O.M.M.A. to take increased damage.\n\nAfterwards, Big M.O.M.M.A. requisitions an additional squadron of drones with |cFF2959D3|Hspell:471585|h[Mobilize Mechadrones]|h|r."},
			{id=30944,title="Tanks",body="$bullet;Big M.O.M.M.A. will |cFF2959D3|Hspell:460156|h[Jumpstart]|h|r after all Darkfuse Mechadrones are defeated.\n$bullet;|cFF2959D3|Hspell:460156|h[Jumpstart]|h|r leaves behind an area of |cFF2959D3|Hspell:473287|h[Excessive Electrification]|h|r.\n$bullet;|cFF2959D3|Hspell:473220|h[Sonic Boom]|h|r continues until it collides with an obstacle."},
			{id=30945,title="Damage Dealers",body="$bullet;Big M.O.M.M.A. will |cFF2959D3|Hspell:460156|h[Jumpstart]|h|r after all Darkfuse Mechadrones are defeated.\n$bullet;|cFF2959D3|Hspell:460156|h[Jumpstart]|h|r causes Big M.O.M.M.A. to take significantly increased damage.\n$bullet;|cFF2959D3|Hspell:473220|h[Sonic Boom]|h|r continues until it collides with an obstacle."},
			{id=30943,title="Healers",body="$bullet;Big M.O.M.M.A. will |cFF2959D3|Hspell:460156|h[Jumpstart]|h|r after all Darkfuse Mechadrones are defeated.\n$bullet;|cFF2959D3|Hspell:460156|h[Jumpstart]|h|r inflicts significant damage to all players.\n$bullet;|cFF2959D3|Hspell:473220|h[Sonic Boom]|h|r continues until it collides with an obstacle."},
