	[2649]={
		encounterID=2649,
		instanceID=1298,
		order=2,
		name="Demolition Duo",
		lore="Keeza Quickfuse and Bront are the Venture Co. brains and brawn duo contracted by Gallywix to implement the \"explosive restructuring\" of the Waterworks dam. Keeza thrives off of wanton destruction, while Bront \"thrives\" off cleaning up the remnants left in her wake.",
		dungeonEncounterID=3019,
		uiMapID=2387,
		pin={x=0.65,y=0.67},
		difficultyIDs={1,2,8,23,205},
		npcIDs={226402,226403},
		displayIDs={122215,123036},
		loot={
			{itemID=234498,diffs={},faction=-1},
			{itemID=234502,diffs={},faction=-1},
			{itemID=234505,diffs={},faction=-1},
			{itemID=232541,diffs={},faction=-1},
			{itemID=234492,diffs={},faction=-1},
			{itemID=246279,diffs={2,23},faction=-1},
		},
		sections={
			{id=30320,title="Overview",body="Keeza Quickfuse blasts players with |cFF2959D3|Hspell:460602|h[Quick Shot]|h|r and her |cFF2959D3|Hspell:473594|h[B.B.B.F.G.]|h|r while planting Ticking Time Bombs with |cFF2959D3|Hspell:460867|h[Big Bada BOOM!]|h|r.\n\nBront |cFF2959D3|Hspell:459799|h[Wallops]|h|r his enemies and |cFF2959D3|Hspell:459779|h[Barreling Charges]|h|r through anything in his path - Ticking Time Bombs included."},
			{id=30950,title="Tanks",body="$bullet;Ticking Time Bombs created by |cFF2959D3|Hspell:460867|h[Big Bada BOOM!]|h|r inflict heavy damage to all players if allowed to expire.\n$bullet;|cFF2959D3|Hspell:459779|h[Barreling Charge]|h|r causes Bront to run through any objects in his path, including Ticking Time Bombs created by |cFF2959D3|Hspell:460867|h[Big Bada BOOM!]|h|r."},
			{id=30951,title="Healers",body="$bullet;Ticking Time Bombs created by |cFF2959D3|Hspell:460867|h[Big Bada BOOM!]|h|r inflict heavy damage to all players if allowed to expire.\n$bullet;|cFF2959D3|Hspell:459779|h[Barreling Charge]|h|r causes Bront to run through any objects in his path, including Ticking Time Bombs created by |cFF2959D3|Hspell:460867|h[Big Bada BOOM!]|h|r.\n$bullet;$[8,23|cFF2959D3|Hspell:473690|h[Kinetic Explosive Gel]|h|r knocks up Ticking Time Bombs nearby when dispelled.$]"},
			{id=30949,title="Damage Dealers",body="$bullet;Ticking Time Bombs created by |cFF2959D3|Hspell:460867|h[Big Bada BOOM!]|h|r inflict heavy damage to all players if allowed to expire.\n$bullet;|cFF2959D3|Hspell:459779|h[Barreling Charge]|h|r causes Bront to run through any objects in his path, including Ticking Time Bombs created by |cFF2959D3|Hspell:460867|h[Big Bada BOOM!]|h|r.\n$bullet;$[8,23|cFF2959D3|Hspell:473690|h[Kinetic Explosive Gel]|h|r knocks up Ticking Time Bombs nearby when dispelled.$]"},
