	[2650]={
		encounterID=2650,
		instanceID=1298,
		order=3,
		name="Swampface",
		lore="Buried beneath the riverbed at the Waterworks lies a hibernating beast. Amidst the commotion around the dam, Swampface awakens and emerges from the mud in a groggy rage to squash the first thing that moves.",
		dungeonEncounterID=3053,
		uiMapID=2387,
		pin={x=0.5125,y=0.73},
		difficultyIDs={1,2,8,23,205},
		npcIDs={226396},
		displayIDs={115575},
		loot={
			{itemID=234506,diffs={},faction=-1},
			{itemID=234495,diffs={},faction=-1},
			{itemID=234499,diffs={},faction=-1},
