			{itemID=246277,diffs={2,23},faction=-1},
		},
		sections={
			{id=31366,title="Overview",body="Swampface ravages the tank with |cFF2959D3|Hspell:469478|h[Sludge Claws]|h|r and rains a ruinous |cFF2959D3|Hspell:473112|h[Mudslide]|h|r from above.\n\n|cFF2959D3|Hspell:473070|h[Awaken the Swamp]|h|r causes eruptions from the earth and a chaos of |cFF2959D3|Hspell:473052|h[Rushing Tides]|h|r that sweep players away."},
			{id=31782,title="Tanks",body="$bullet;|cFF2959D3|Hspell:469478|h[Sludge Claws]|h|r inflict massive damage and cause healing to be absorbed.\n$bullet;|cFF2959D3|Hspell:473112|h[Mudslide]|h|r  inflicts heavy damage in a massive line.\n$bullet;|cFF2959D3|Hspell:473052|h[Rushing Tides]|h|r inflict damage and sweep away players caught inside."},
			{id=31783,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:473112|h[Mudslide]|h|r  inflicts heavy damage in a massive line.\n$bullet;|cFF2959D3|Hspell:473052|h[Rushing Tides]|h|r inflict damage and sweep away players caught inside.",difficultyIDs={1,2}},
			{id=31368,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:470039|h[Razorchoke Vines]|h|r yank players together when too far apart.\n$bullet;|cFF2959D3|Hspell:473112|h[Mudslide]|h|r  inflicts heavy damage in a massive line.\n$bullet;|cFF2959D3|Hspell:473052|h[Rushing Tides]|h|r inflict damage and sweep away players caught inside.",difficultyIDs={8,23}},
			{id=31784,title="Healers",body="$bullet;|cFF2959D3|Hspell:473112|h[Mudslide]|h|r  inflicts heavy damage in a massive line.\n$bullet;|cFF2959D3|Hspell:473052|h[Rushing Tides]|h|r inflict damage and sweep away players caught inside.",difficultyIDs={1,2}},
