	[2651]={
		encounterID=2651,
		instanceID=1298,
		order=4,
		name="Geezle Gigazap",
		lore="At the heart of the Waterworks dam, the electric mastermind Geezle Gigazap siphons power for \"THE PROJECT\". When he is cornered and Gallywix's secret plans have nearly come to a halt, Geezle reroutes the power headed to the Undermine... to himself!",
		dungeonEncounterID=3054,
		uiMapID=2388,
		pin={x=0.652,y=0.81},
		difficultyIDs={1,2,8,23,205},
		npcIDs={236950},
		displayIDs={124579},
		loot={
			{itemID=234501,diffs={},faction=-1},
			{itemID=234504,diffs={},faction=-1},
			{itemID=232545,diffs={},faction=-1},
