			{itemID=246274,diffs={2,23},faction=-1},
			{itemID=234507,diffs={2,23},faction=-1},
		},
		sections={
			{id=30480,title="Overview",body="Geezle siphons massive power from the generator during |cFF2959D3|Hspell:465463|h[Turbo Charge]|h|r, causing the Waterworks to destabilize and collapse. \n\nGeezle then fries his enemies with an array of voltaic attacks as |cFF2959D3|Hspell:468846|h[Leaping Sparks]|h|r pursue players to their electrocution in the depths of the dam."},
			{id=31955,title="Tanks",body="$bullet;|cFF2959D3|Hspell:466190|h[Thunder Punch]|h|r inflicts massive damage and knocks the target back.\n$bullet;|cFF2959D3|Hspell:465279|h[Dam Water]|h|r electrifies upon contact with Geezle's lightning abilities.\n$bullet;|cFF2959D3|Hspell:468846|h[Leaping Sparks]|h|r pursue players and stun them upon contact."},
			{id=31956,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:468846|h[Leaping Sparks]|h|r pursue players and stun them upon contact.\n$bullet;|cFF2959D3|Hspell:465279|h[Dam Water]|h|r electrifies upon contact with Geezle's lightning abilities.\n$bullet;|cFF2959D3|Hspell:465463|h[Turbo Charge]|h|r and |cFF2959D3|Hspell:468813|h[Gigazap]|h|r inflict heavy damage."},
			{id=31957,title="Healers",body="$bullet;|cFF2959D3|Hspell:465463|h[Turbo Charge]|h|r and |cFF2959D3|Hspell:468813|h[Gigazap]|h|r inflict heavy damage.\n$bullet;|cFF2959D3|Hspell:468846|h[Leaping Sparks]|h|r pursue players and stun them upon contact.\n$bullet;|cFF2959D3|Hspell:465279|h[Dam Water]|h|r electrifies upon contact with Geezle's lightning abilities."},
			{id=30484,title="Section 5"},
