	[2653]={
		encounterID=2653,
		instanceID=1296,
		order=5,
		name="Sprocketmonger Lockenstock",
		lore="As one of Gallywix's top minds, Sprocketmonger Lockenstock cannot say no to innovation, meaning that his list of inventions stretches far longer than the conveyor belts in his refinery. Constantly looking to simultaneously cut both corners and costs, Lockenstock's always searching for new markets to test out his gadgets.",
