		sections={
			{id=30421,title="Overview",body="Sprocketmonger Lockenstock prepares a demonstration for the players while slowly gaining energy. Conveyor belts around the factory produce explosive new technology for Lockenstock to |cFF2959D3|Hspell:473276|h[Activate Inventions!]|h|r .\n\nUpon reaching 100 energy, Lockenstock prepares a |cFF2959D3|Hspell:466765|h[Beta Launch]|h|r of an improved contraption, infusing it with void powers before renewing his assault."},
			{id=31780,title="Tanks",body="$bullet;Each application of |cFF2959D3|Hspell:465917|h[Gravi-Gunk]|h|r increases all damage taken.\n$bullet;The damage of |cFF2959D3|Hspell:1214872|h[Pyro Party Pack]|h|r is reduced the further the target is from other players.\n$bullet;|cFF2959D3|Hspell:1217083|h[Foot-Blasters]|h|r cause an |cFF2959D3|Hspell:1216406|h[Unstable Explosion]|h|r that increases damage taken by |cFF2959D3|Hspell:1216406|h[Unstable Explosion]|h|r for a short duration.",difficultyIDs={15,16}},
			{id=30422,title="Tanks",body="$bullet;Each application of |cFF2959D3|Hspell:465917|h[Gravi-Gunk]|h|r increases all damage taken.\n$bullet;The damage of |cFF2959D3|Hspell:1214872|h[Pyro Party Pack]|h|r is reduced the further the target is from other players.",difficultyIDs={14,17}},
			{id=31778,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:1217083|h[Foot-Blasters]|h|r cause an |cFF2959D3|Hspell:1216406|h[Unstable Explosion]|h|r that increases damage taken by |cFF2959D3|Hspell:1216406|h[Unstable Explosion]|h|r for a short duration.\n$bullet;Players designated as |cFF2959D3|Hspell:1216508|h[Screw Ups]|h|r periodically drop drills at their location.\n$bullet;|cFF2959D3|Hspell:466235|h[Wire Transfer]|h|r inflicts significant damage to players standing within the effect",difficultyIDs={15,16}},
			{id=32939,title="Damage Dealers",body="$bullet;Players designated as |cFF2959D3|Hspell:1216508|h[Screw Ups]|h|r periodically drop drills at their location.\n$bullet;|cFF2959D3|Hspell:466235|h[Wire Transfer]|h|r inflicts significant damage to players standing within the effect",difficultyIDs={14}},
			{id=30423,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:466235|h[Wire Transfer]|h|r inflicts significant damage to players standing within the effect",difficultyIDs={17}},
			{id=31779,title="Healers",body="$bullet;|cFF2959D3|Hspell:465232|h[Sonic Ba-Boom]|h|r applies a damage over time effect to all players.\n$bullet;|cFF2959D3|Hspell:1217083|h[Foot-Blasters]|h|r cause an |cFF2959D3|Hspell:1216406|h[Unstable Explosion]|h|r that increases damage taken by |cFF2959D3|Hspell:1216406|h[Unstable Explosion]|h|r for a short duration.\n$bullet;|cFF2959D3|Hspell:1218319|h[Voidsplosion]|h|r inflicts significant damage to all players and absorbs healing taken.",difficultyIDs={15,16}},
			{id=30424,title="Healers",body="$bullet;|cFF2959D3|Hspell:465232|h[Sonic Ba-Boom]|h|r applies a damage over time effect to all players.\n$bullet;|cFF2959D3|Hspell:1218319|h[Voidsplosion]|h|r inflicts significant damage to all players and absorbs healing taken.",difficultyIDs={14,17}},
			{id=30425,title="Stage One: Assembly Required"},
