	[2675]={
		encounterID=2675,
		instanceID=1303,
		order=1,
		name="Azhiccar",
		lore="Devourers often travel in the wake of the Great Devourer Worms to reach new realms to feast on. Azhiccar is no exception. It burrows into a new land, seeking to satiate its endless hunger. Sometimes even other devourers fall prey, but the devourers still answer Azhiccar's call--to consume or be consumed in its vortex of endless hunger.",
		dungeonEncounterID=3107,
		uiMapID=2449,
		pin={x=0.614,y=0.842},
		difficultyIDs={1,2,8,23,205},
		npcIDs={234893},
		displayIDs={97762,101978},
		loot={
			{itemID=242468,diffs={},faction=-1},
			{itemID=242473,diffs={},faction=-1},
			{itemID=242472,diffs={},faction=-1},
			{itemID=242475,diffs={},faction=-1},
			{itemID=242497,diffs={},faction=-1},
			{itemID=242470,diffs={},faction=-1},
			{itemID=242464,diffs={},faction=-1},
		},
		sections={
			{id=31220,title="Overview",body="Azhiccar bombards players with |cFF2959D3|Hspell:1217436|h[Toxic Regurgitation]|h|r and periodically calls forth an invasion of Frenzied Mites that |cFF2959D3|Hspell:1217381|h[Engorge]|h|r themselves on players.\n\nUpon reaching 100 energy, Azhiccar attempts to |cFF2959D3|Hspell:1217232|h[Devour]|h|r all players and creatures, healing and becoming stronger with every living creature consumed."},
			{id=31221,title="Tanks",body="$bullet;|cFF2959D3|Hspell:1217327|h[Invading Shriek]|h|r calls forth Frenzied Mites that fixate on random players and fly between them wildly.\n$bullet;Azhiccar uses |cFF2959D3|Hspell:1217232|h[Devour]|h|r to draw in living players and Frenzied Mites and |cFF2959D3|Hspell:1217241|h[Feast]|h|r on them.\n$bullet;|cFF2959D3|Hspell:1217241|h[Feast]|h|r causes Azhiccar to heal and inflict increased damage for every player or creature consumed."},
			{id=31222,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:1217327|h[Invading Shriek]|h|r calls forth Frenzied Mites that fixate on random players and fly between them wildly.\n$bullet;Azhiccar uses |cFF2959D3|Hspell:1217232|h[Devour]|h|r to draw in living players and Frenzied Mites and |cFF2959D3|Hspell:1217241|h[Feast]|h|r on them.\n$bullet;|cFF2959D3|Hspell:1217241|h[Feast]|h|r causes Azhiccar to heal and inflict increased damage for every player or creature consumed."},
			{id=31223,title="Healers",body="$bullet;|cFF2959D3|Hspell:1217436|h[Toxic Regurgitation]|h|r inflicts Shadow damage to afflicted players.\n$bullet;Azhiccar uses |cFF2959D3|Hspell:1217232|h[Devour]|h|r to draw in living players and Frenzied Mites and |cFF2959D3|Hspell:1217241|h[Feast]|h|r on them.\n$bullet;|cFF2959D3|Hspell:1217241|h[Feast]|h|r causes Azhiccar to heal and inflict increased damage for every player or creature consumed."},
			{id=32688,title="Stage One: <PH>",difficultyIDs={1,2,24,205}},
			{id=32689,title="Section 6"},
			{id=31224,title="Stage One: <PH>",body="$[!8,23,\n\nOn Mythic difficulty, Frenzied Mites are called when Devour begins.$]",difficultyIDs={8,23}},
			{id=31378,title="Section 6"},
