	[2676]={
		encounterID=2676,
		instanceID=1303,
		order=2,
		name="Taah'bat and A'wazj",
		lore="As Soul-Scribe's right hand, Taah'bat will stop at nothing to see her will done. The beast master has bound himself to the wild warp-stalker, A'wazj, and mastered its unique talents. Now the pair act as one, slipping in and out of phase to strike any who threaten Soul-Scribe's revenge.",
		dungeonEncounterID=3108,
		uiMapID=2449,
		pin={x=0.5663,y=0.4466},
		difficultyIDs={1,2,8,23,205},
		npcIDs={234933,237514},
		displayIDs={123825,126474},
		loot={
			{itemID=242477,diffs={},faction=-1},
			{itemID=242482,diffs={},faction=-1},
			{itemID=242483,diffs={},faction=-1},
			{itemID=242479,diffs={},faction=-1},
			{itemID=242495,diffs={},faction=-1},
			{itemID=242481,diffs={},faction=-1},
			{itemID=242476,diffs={},faction=-1},
		},
		sections={
			{id=31227,title="Overview",body="Taah'bat begins the encounter mounted on A'wazj, launching attacks  in a coordinated effort.\n\nUpon reaching 100 energy, Taah'bat dismounts A'wazj and begins |cFF2959D3|Hspell:1219700|h[Arcane Blitz]|h|r. Upon breaking all applications of |cFF2959D3|Hspell:1219457|h[Incorporeal]|h|r, both Taah'bat and A'wazj become |cFF2959D3|Hspell:1219731|h[Destabilized]|h|r and return to fight as one."},
			{id=31228,title="Tanks",body="$bullet;Striking Taah'bat with |cFF2959D3|Hspell:1220384|h[Warp Strike]|h|r during |cFF2959D3|Hspell:1219700|h[Arcane Blitz]|h|r removes an application of |cFF2959D3|Hspell:1219457|h[Incorporeal]|h|r.\n$bullet;|cFF2959D3|Hspell:1219482|h[Rift Claws]|h|r inflicts high Arcane damage to the target and causes them to bleed."},
			{id=31229,title="Damage Dealers",body="$bullet;Striking Taah'bat with |cFF2959D3|Hspell:1220384|h[Warp Strike]|h|r during |cFF2959D3|Hspell:1219700|h[Arcane Blitz]|h|r removes an application of |cFF2959D3|Hspell:1219457|h[Incorporeal]|h|r.\n$bullet;|cFF2959D3|Hspell:1219536|h[Binding Javelin]|h|r inflicts stacking damage to affected players until defeated."},
			{id=31230,title="Healers",body="$bullet;Striking Taah'bat with |cFF2959D3|Hspell:1220384|h[Warp Strike]|h|r during |cFF2959D3|Hspell:1219700|h[Arcane Blitz]|h|r removes an application of |cFF2959D3|Hspell:1219457|h[Incorporeal]|h|r.\n$bullet;|cFF2959D3|Hspell:1220497|h[Arcane Overload]|h|r inflicts Arcane damage to all players.\n$bullet;|cFF2959D3|Hspell:1219536|h[Binding Javelin]|h|r inflicts stacking damage to affected players until defeated."},
			{id=31232,title="Section 7"},
			{id=31584,title="Arcane Blitz"},
			{id=31231,title="Taah'bat"},
			{id=31551,title="Section 8"},
			{id=31591,title="Section 15"},
			{id=31587,title="Section 13"},
			{id=31585,title="A'wazj"},
			{id=31586,title="Section 8"},
			{id=33679,title="Section 16",difficultyIDs={1,2,24,205}},
			{id=31592,title="Section 16",body="$[!8,23,\n\nOn Mythic difficulty, A'wazj targets an additional target for Binding Javelin.$]",difficultyIDs={8,23}},
