	[2677]={
		encounterID=2677,
		instanceID=1303,
		order=3,
		name="Soul-Scribe",
		lore="The Soul-Scribe once led the oracles of K'aresh, but the destruction of her world drove them into the wastelands, where they began a crusade of revenge. She has given ancient oaths to destroy the enemies of Salhadaar, and all they have built. With her ancient powers rediscovered, the fate of this dome looks grim.",
		dungeonEncounterID=3109,
		uiMapID=2449,
		pin={x=0.2577,y=0.3571},
		difficultyIDs={1,2,8,23,205},
		npcIDs={230292,230645,240858,245156,249507},
		displayIDs={126804},
		loot={
			{itemID=242491,diffs={},faction=-1},
			{itemID=242490,diffs={},faction=-1},
			{itemID=242486,diffs={},faction=-1},
			{itemID=242488,diffs={},faction=-1},
			{itemID=242494,diffs={},faction=-1},
			{itemID=242484,diffs={},faction=-1},
			{itemID=242487,diffs={},faction=-1},
			{itemID=242493,diffs={},faction=-1},
		},
		sections={
			{id=31234,title="Overview",body="Soul-Scribe uses |cFF2959D3|Hspell:1224793|h[Whispers of Fate]|h|r to create echoes of players' Fates. Soul-Scribe casts |cFF2959D3|Hspell:1225162|h[Ceremonial Dagger]|h|r and |cFF2959D3|Hspell:1225218|h[Dread of the Unknown]|h|r in an attempt to harm the Fates.  \n\nUpon reaching 100 energy, Soul-Scribe casts |cFF2959D3|Hspell:1236703|h[Eternal Weave]|h|r."},
			{id=31235,title="Tanks",body="$bullet;When a player's Fate is struck by Soul-Scribe's abilities the player bound to that Fate is afflicted with |cFF2959D3|Hspell:1226444|h[Wounded Fate]|h|r.\n$bullet;|cFF2959D3|Hspell:1225218|h[Dread of the Unknown]|h|r inflicts heavy Arcane damage to players and Fates within the detonation."},
			{id=31236,title="Damage Dealers",body="$bullet;When a player's Fate is struck by Soul-Scribe's abilities the player bound to that Fate is afflicted with |cFF2959D3|Hspell:1226444|h[Wounded Fate]|h|r.\n$bullet;|cFF2959D3|Hspell:1225218|h[Dread of the Unknown]|h|r inflicts heavy Arcane damage to players and Fates within the detonation."},
			{id=31237,title="Healers",body="$bullet;When a player's Fate is struck by Soul-Scribe's abilities the player bound to that Fate is afflicted with |cFF2959D3|Hspell:1226444|h[Wounded Fate]|h|r.\n$bullet;|cFF2959D3|Hspell:1225218|h[Dread of the Unknown]|h|r inflicts heavy Arcane damage to players and Fates within the detonation."},
			{id=31238,title="Stage One: <PH>"},
			{id=32012,title="Section 6"},
