	[2683]={
		encounterID=2683,
		instanceID=1278,
		order=5,
		name="The Gobfather",
		lore="Once a source of pride for the Bilgewater Cartel, this mech was a force to be reckoned with in the Demolition Dome. A pinnacle of goblin innovation... until someone forgot to give it an oil change. Now the King of the Demo Dome has gone haywire, running amok and threatening to unleash havoc upon the citizens of Undermine.",
		dungeonEncounterID=3128,
		pin={x=0.5,y=0.5},
		difficultyIDs={14},
		npcIDs={231821},
		displayIDs={49134,123059},
		loot={
			{itemID=232733,diffs={},faction=-1},
			{itemID=232726,diffs={},faction=-1},
			{itemID=232725,diffs={},faction=-1},
