	[2684]={
		encounterID=2684,
		instanceID=1302,
		order=1,
		name="Plexus Sentinel",
		lore="The Plexus Sentinel patrols the colossal machinery of Manaforge Omega, ensuring that energy from the shattered world of K'aresh is filtered through the structure's conduits. All incoming energy must be sterilized. All pollutants must be purged.",
		dungeonEncounterID=3129,
