		sections={
			{id=32283,title="Section 1",body="Loom'ithar traps enemies within its chamber with |cFF2959D3|Hspell:1237272|h[Lair Weaving]|h|r and unleashes infused arcane energy with |cFF2959D3|Hspell:1226395|h[Overinfusion Burst]|h|r. \n\nUpon reaching 50% health, Loom'ithar tears itself in two and attacks players directly with |cFF2959D3|Hspell:1227227|h[Writhing Wave]|h|r."},
			{id=32284,title="Tank",body="$bullet;|cFF2959D3|Hspell:1227263|h[Piercing Strand]|h|r causes all targets hit to take increased damage from it for a duration.\n$bullet; |cFF2959D3|Hspell:1227226|h[Writhing Wave]|h|r is split between all targets caught in its area.\n$bullet; Loom'ithar will give chase to their target while consumed with |cFF2959D3|Hspell:1228059|h[Unbound Rage]|h|r"},
			{id=32285,title="Damage Dealers",body="$bullet; Infused Tangles inflict heavy damage if players are caught in the collapsing ring of threads.\n$bullet; |cFF2959D3|Hspell:1226315|h[Infusion Tether]|h|r will inflict damge indefinitely until the effect ends.\n$bullet; |cFF2959D3|Hspell:1226366|h[Living Silk]|h|r inflicts heavy Nature damage and reduces movement speed."},
			{id=32286,title="Healers",body="$bullet; |cFF2959D3|Hspell:1226315|h[Infusion Tether]|h|r must be pulled far away from Loom'ithar to end the effect.\n$bullet; |cFF2959D3|Hspell:1226395|h[Overinfusion Burst]|h|r inflicts Arcane damage as it charges and a massive burst when it ends.\n$bullet; |cFF2959D3|Hspell:1226366|h[Living Silk]|h|r inflicts heavy Nature damage and reduces movement speed."},
			{id=32296,title="Stage One: The Arcane Loom"},
			{id=32924,title="Section 24",body="$[!15,16\n\nOn Heroic and Mythic difficulties, Infused Tangles are protected by a Woven Ward.$]",difficultyIDs={14,15,16}},
			{id=33236,title="Section 23",difficultyIDs={15,16}},
			{id=33458,title="Section 24",difficultyIDs={16}},
			{id=33671,title="Section 26",difficultyIDs={16}},
			{id=33697,title="Section 26",difficultyIDs={16}},
			{id=32926,title="Section 6",body="$[!15,16\n\nOn Heroic and Mythic difficulties, if the target is standing in Living Silk, Infusion Tether applies Silken Snare when it ends .$]"},
