		sections={
			{id=32366,title="Overview",body="Forgeweaver Araz activates the |cFF2959D3|Hspell:1237322|h[Prime Sequence]|h|r of Arcane Collectors throughout the room. Once all collectors are active, Araz begins an arcane ritual to summon Dimensius.\n\nDisrupting this ritual twice forces Araz's hand as he activates the final sequence, forming a |cFF2959D3|Hspell:1233076|h[Dark Singularity]|h|r."},
			{id=33700,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:1228214|h[Astral Harvest]|h|r creates manifestations that cause an |cFF2959D3|Hspell:1236207|h[Astral Surge]|h|r when they reach Arcane Collectors.\n$bullet;Arcane Echoes duplicate Forgeweaver Araz's abilities.\n$bullet;Arcane Collectors lose their |cFF2959D3|Hspell:1231726|h[Arcane Barrier]|h|r during the intermission.",difficultyIDs={14,15,17}},
			{id=32369,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:1228214|h[Astral Harvest]|h|r creates manifestations that cause an |cFF2959D3|Hspell:1236207|h[Astral Surge]|h|r when they reach Arcane Collectors.\n$bullet;Arcane Echoes duplicate Forgeweaver Araz's abilities.\n$bullet;Arcane Collectors lose their|cFF2959D3|Hspell:1231726|h[Arcane Barrier]|h|r during the intermission.\n$bullet;Arcane Collectors inflict massive damage with |cFF2959D3|Hspell:1243272|h[Containment Breach]|h|r when destroyed.",difficultyIDs={16}},
			{id=32368,title="Healers",body="$bullet;|cFF2959D3|Hspell:1228214|h[Astral Harvest]|h|r inflicts high periodic damage to its target.\n$bullet;|cFF2959D3|Hspell:1228218|h[Arcane Obliteration]|h|r inflicts damage to everyone that is reduced by the number of players at the impact location.\n$bullet;|cFF2959D3|Hspell:1240705|h[Astral Burn]|h|r continously ramps damage during the intermission."},
			{id=32952,title="Tanks",body="$bullet;|cFF2959D3|Hspell:1228502|h[Overwhelming Power]|h|r continously stacks on Araz's current target.\n$bullet;|cFF2959D3|Hspell:1226260|h[Arcane Convergence]|h|r inflicts damage to the raid on completion.",difficultyIDs={14,17}},
			{id=32367,title="Tanks",body="$bullet;|cFF2959D3|Hspell:1228502|h[Overwhelming Power]|h|r continously stacks on Araz's current target.\n$bullet;|cFF2959D3|Hspell:1228454|h[Mark of Power]|h|r activates while Araz is close to one of his echoes.\n$bullet;|cFF2959D3|Hspell:1226260|h[Arcane Convergence]|h|r inflicts damage to the raid each time it connects with the Manaforge.",difficultyIDs={15,16}},
			{id=33699,title="Stage One: Priming the Forge",body="Forgeweaver Araz funnels energy into the Manaforge to feed Dimensius."},
