			{id=32337,title="Section 25",body="$[!15,16\n\nIn Heroic and Mythic difficulty, |cFF2959D3|Hspell:1227809|h[The Hunt]|h|r inflicts damage in an area around players along the path to her prey.$]",difficultyIDs={15}},
			{id=33299,title="Section 25",body="$[!16\n\nIn Mythic difficulty, |cFF2959D3|Hspell:1227809|h[The Hunt]|h|r marks multiple players simultaneously and players in the path of |cFF2959D3|Hspell:1227809|h[The Hunt]|h|r are afflicted with |cFF2959D3|Hspell:1247415|h[Weakened Prey]|h|r.$]",difficultyIDs={16}},
