	[2690]={
		encounterID=2690,
		instanceID=1302,
		order=7,
		name="Nexus-King Salhadaar",
		lore="The former ruler of K'aresh and sworn enemy of Dimensius, Nexus-King Salhadaar has emerged unbroken from the shattered husk of K'aresh. Atop his Royal Voidwing, Salhadaar now commands the ultimate will of the Shadowguard. Oaths will be fulfilled. All will be made to serve.",
		dungeonEncounterID=3134,
		uiMapID=2466,
		pin={x=0.4987,y=0.5573},
		difficultyIDs={14,15,16,17,220,241},
		npcIDs={237763,245826,245882},
		displayIDs={125691,126550,126889,128081,128326,128327},
		loot={
			{itemID=242403,diffs={},faction=-1},
			{itemID=237734,diffs={},faction=-1},
